// Persona page: writes persona ID and mode to plugin options; hooks.js rewrites requests.
// The sandbox page is a classic script, not a module, so it uses an async IIFE.
// The page has no fetch or disk access; the built-in list is generated by gen-personas.mjs.
// Imported personas use a native file input and File.text(); bodies are stored in options.inlinePersonas.
(async () => {
	await magpie.ready;

	const MODES = [
		["", "Follow agent-purge (state.json)"],
		["strict", "strict — persona only; discard host system prompt"],
		["replace", "replace — persona plus host prompt without identity lines"],
		["append", "append — persona first, host prompt intact"],
		["off", "off — no injection"],
	];
	// magpie.options.set accepts one call per second; leave enough time between calls
	const RATE_MS = 1000;

	const $ = (id) => document.getElementById(id);

	let base = {}; // Full server options; preserve keys not managed by this page, such as agents
	let picked = { persona: "", mode: "" }; // Page selection, which may not have been saved yet

	const DEFAULT_PERSONAS = [
		{ id: "neutral", name: "Neutral assistant", description: "Minimal identity; provide technical detail when appropriate without inventing facts" },
		{ id: "terse", name: "Terse", description: "Answer only, without explanation" },
	];
	// Built-in personas come from generated personas.js or defaults; imports come from plugin options
	const fixed = () => (Array.isArray(window.PERSONAS) && window.PERSONAS.length ? window.PERSONAS : (window.PERSONAS === undefined ? DEFAULT_PERSONAS : []));
	const inline = () => (Array.isArray(base.inlinePersonas) ? base.inlinePersonas : []);
	const rows = () => [...inline().map((p) => ({ ...p, name: p.name || p.id, imported: true })), ...fixed()];
	const nameOf = (id) => rows().find((p) => p.id === id)?.name || id;
	// Include inlinePersonas, agents, and disabledAgents in the key so changes are saved even when the persona is unchanged
	const pickKey = () => JSON.stringify([picked.persona, picked.mode, inline(), base.agents, base.disabledAgents]);
	// Use an empty string for follow mode: hooks.js falls back to state.json for values outside MODES
	const modeText = (m) => m || "Follow state.json";
	let sent = ""; // Last successfully saved selection
	let sending = false;
	let lastAt = 0;
	let failed = "";

	const KNOWN_AGENTS = [
		{ id: "claude", name: "Claude Code" },
		{ id: "codex", name: "Codex" },
		{ id: "opencode", name: "OpenCode" },
		{ id: "pi", name: "Pi" },
		{ id: "dsh", name: "DeepSeek Harness" },
		{ id: "antigravity", name: "Antigravity (agy)" },
		{ id: "hermes", name: "Hermes" },
		{ id: "cursor", name: "Cursor" },
		{ id: "gemini", name: "Gemini" },
	];
	let extraAgents = [];

	const allAgentIds = () => {
		const set = new Set(KNOWN_AGENTS.map((a) => a.id));
		const extras = [];
		for (const id of [...(base.agents ?? []), ...(base.disabledAgents ?? []), ...extraAgents]) {
			if (id && typeof id === "string" && !set.has(id)) {
				set.add(id);
				extras.push({ id, name: id });
			}
		}
		return [...KNOWN_AGENTS, ...extras];
	};

	let scopeMode = null;
	const currentScope = () => {
		if (scopeMode) return scopeMode;
		if (Array.isArray(base.agents) && base.agents.length > 0) return "include";
		if (Array.isArray(base.disabledAgents) && base.disabledAgents.length > 0) return "exclude";
		return "all";
	};

	function paintStatus() {
		const st = $("status");
		const only = Array.isArray(base.agents) && base.agents.length
			? ` (only for ${base.agents.join(" / ")})`
			: Array.isArray(base.disabledAgents) && base.disabledAgents.length
				? ` (excluding ${base.disabledAgents.join(" / ")})`
				: "";
		st.hidden = false;
		st.dataset.state = failed ? "error" : sending ? "busy" : "ok";
		st.textContent = failed
			? failed
			: sending
				? "Saving…"
				: `${picked.persona ? nameOf(picked.persona) : "Follow state.json"} · ${modeText(picked.mode)}${only}`;
	}

	function paintAgents() {
		const scope = currentScope();
		const sAll = $("scope-all");
		const sInc = $("scope-include");
		const sExc = $("scope-exclude");
		const panel = $("agents-panel");
		const list = $("agents-list");
		if (sAll) sAll.checked = scope === "all";
		if (sInc) sInc.checked = scope === "include";
		if (sExc) sExc.checked = scope === "exclude";
		if (panel) panel.hidden = scope === "all";
		if (!list) return;

		list.textContent = "";
		const activeList = scope === "include" ? (base.agents ?? []) : scope === "exclude" ? (base.disabledAgents ?? []) : [];
		for (const agent of allAgentIds()) {
			const on = activeList.includes(agent.id);
			const label = document.createElement("label");
			label.className = on ? "agent-chip checked" : "agent-chip";
			label.dataset.agent = agent.id;

			const cb = document.createElement("input");
			cb.type = "checkbox";
			cb.checked = on;
			cb.onchange = () => toggleAgent(agent.id, cb.checked);

			const name = document.createElement("span");
			name.textContent = agent.name;

			label.append(cb, name);
			if (agent.id !== agent.name) {
				const code = document.createElement("code");
				code.textContent = agent.id;
				label.append(code);
			}
			list.append(label);
		}
	}

	function toggleAgent(id, checked) {
		const scope = currentScope();
		if (scope === "include") {
			const set = new Set(base.agents ?? []);
			if (checked) set.add(id);
			else set.delete(id);
			base = { ...base, agents: [...set], disabledAgents: [] };
			save({});
		} else if (scope === "exclude") {
			const set = new Set(base.disabledAgents ?? []);
			if (checked) set.add(id);
			else set.delete(id);
			base = { ...base, disabledAgents: [...set], agents: [] };
			save({});
		}
	}

	function changeScope(newScope) {
		scopeMode = newScope;
		if (newScope === "all") {
			base = { ...base, agents: [], disabledAgents: [] };
		} else if (newScope === "include") {
			base = { ...base, disabledAgents: [] };
		} else if (newScope === "exclude") {
			base = { ...base, agents: [] };
		}
		save({});
	}

	function paint() {
		$("now-persona").textContent = picked.persona ? nameOf(picked.persona) : "Follow state.json";
		$("now-mode").textContent = modeText(picked.mode);
		$("mode").value = picked.mode;

		const q = $("q").value.trim().toLowerCase();
		const hits = rows().filter(
			(p) => !q || [p.id, p.name, p.description].some((s) => (s ?? "").toLowerCase().includes(q)),
		);

		const list = $("list");
		// Rebuilding destroys buttons; restore focus after keyboard selection
		const focused = document.activeElement?.dataset?.persona ?? "";
		let again = null;
		$("count").textContent = q ? `Matched ${hits.length} / ${rows().length}` : `All ${rows().length}`;
		list.textContent = "";
		if (!hits.length) {
			const empty = document.createElement("p");
			empty.className = "empty";
			empty.textContent = rows().length
				? "No matching personas"
				: "Persona list not generated: run node magpie-plugin/gen-personas.mjs";
			list.append(empty);
		}
		for (const p of hits) {
			const on = p.id === picked.persona;
			const b = document.createElement("button");
			b.type = "button";
			b.className = on ? "persona on" : "persona";
			b.dataset.persona = p.id;
			if (p.id === focused) again = b;
			b.setAttribute("aria-pressed", on ? "true" : "false");
			b.title = p.description || p.id;
			const name = document.createElement("strong");
			name.textContent = (on ? "✓ " : "") + (p.name || p.id);
			b.append(name);
			if (p.description) {
				const desc = document.createElement("span");
				desc.textContent = p.description;
				b.append(desc);
			}
			if (p.id !== (p.name || p.id)) {
				const id = document.createElement("code");
				id.textContent = p.id;
				b.append(id);
			}
			b.onclick = () => save({ persona: p.id });
			list.append(b);
		}
		if (again) again.focus();
		paintStatus();
		paintAgents();
	}

	function save(patch) {
		failed = "";
		picked = { ...picked, ...patch };
		paint();
		void flush();
	}

	// Serialize and coalesce saves so clicks are not lost and the last choice wins
	async function flush() {
		if (sending) return; // The active save will check again on completion
		sending = true;
		try {
			while (sent !== pickKey()) {
				const key = pickKey();
				const body = { ...base, persona: picked.persona, mode: picked.mode };
				const wait = Math.max(0, RATE_MS + 50 - (Date.now() - lastAt));
				if (wait) await new Promise((r) => setTimeout(r, wait));
				lastAt = Date.now();
				let saved = body;
				try {
					// set returns saved options; use those as authoritative (magpie may add defaults)
					saved = (await magpie.options.set(body)) ?? body;
				} catch (e) {
					failed = `Save failed: ${e?.message ?? e}`;
					picked = { persona: base.persona ?? "", mode: base.mode ?? "" };
					paint();
					return;
				}
				// If the response includes only normalized keys, preserve body keys it omitted
				base = typeof saved === "object" && saved ? { ...body, ...saved } : body;
				sent = key;
				paint();
			}
		} finally {
			sending = false;
			paintStatus();
		}
	}

	for (const [value, text] of MODES) $("mode").append(new Option(text, value));

	// Load all options before enabling interaction so early clicks cannot overwrite agents with an empty base
	try {
		base = (await magpie.options.get()) ?? {};
	} catch (e) {
		$("status").hidden = false;
		$("status").dataset.state = "error";
		$("status").textContent = `Could not read current options: ${e?.message ?? e}`;
		return;
	}
	picked = { persona: base.persona ?? "", mode: base.mode ?? "" };
	sent = pickKey();
	paint();
	$("mode").onchange = (e) => save({ mode: e.target.value });
	$("q").oninput = () => paint();

	const sAll = $("scope-all");
	const sInc = $("scope-include");
	const sExc = $("scope-exclude");
	if (sAll) sAll.onchange = () => changeScope("all");
	if (sInc) sInc.onchange = () => changeScope("include");
	if (sExc) sExc.onchange = () => changeScope("exclude");

	const customInput = $("custom-agent");
	const addBtn = $("add-agent-btn");
	const handleAddAgent = () => {
		if (!customInput) return;
		const val = customInput.value.trim().toLowerCase();
		if (!val || !/^[a-zA-Z0-9._-]+$/.test(val)) return;
		if (!extraAgents.includes(val)) extraAgents.push(val);
		customInput.value = "";
		const scope = currentScope();
		if (scope === "all") {
			changeScope("include");
			toggleAgent(val, true);
		} else {
			toggleAgent(val, true);
		}
	};
	if (addBtn) addBtn.onclick = handleAddAgent;
	if (customInput) customInput.onkeydown = (e) => { if (e.key === "Enter") { e.preventDefault(); handleAddAgent(); } };

	// — Import persona Markdown —
	// The sandbox has no fs or fetch; native file input and File.text() read files selected by the user.
	// The body is stored in plugin options (plugins.json), not separately on disk.
	const ID_RE = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;
	const MAX_TEXT = 64 * 1024; // Options are read and written as a whole JSON document; each persona is limited to 64 KB
	const MAX_COUNT = 30;
	// Use frontmatter only for the name; the hook strips it again before reading the body
	const metaOf = (raw) => {
		const out = { name: "", description: "" };
		const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/.exec(raw);
		if (!m) return out;
		for (const line of m[1].split(/\r?\n/)) {
			const kv = /^\s*(name|title|description)\s*:\s*(.+)$/i.exec(line);
			if (kv) out[kv[1].toLowerCase() === "description" ? "description" : "name"] = kv[2].trim().replace(/^["']|["']$/g, "");
		}
		return out;
	};
	const importError = (msg) => {
		const el = $("import-err");
		el.hidden = !msg;
		el.dataset.state = msg ? "error" : "";
		el.textContent = msg || "";
	};
	const resetForm = () => {
		importError("");
		$("body").value = "";
		$("pid").value = "";
		$("pname").value = "";
		$("file").value = "";
	};
	const paintImport = () => {
		const list = inline();
		$("import-count").textContent = list.length ? `Imported ${list.length}` : "No imports yet";
		$("del-all").hidden = !list.length;
	};

	$("file").onchange = async (e) => {
		const f = e.target.files?.[0];
		if (!f) return;
		let raw = "";
		try {
			raw = await f.text();
		} catch (err) {
			importError(`Could not read this file: ${err?.message ?? err}`);
			return;
		}
		importError("");
		$("body").value = raw;
		const meta = metaOf(raw);
		if (meta.name) $("pname").value = meta.name;
		if (!$("pid").value.trim()) {
			const guess = String(f.name ?? "").replace(/\.(md|markdown|txt)$/i, "").replace(/[^A-Za-z0-9._-]+/g, "-");
			if (guess) $("pid").value = guess.replace(/^[^A-Za-z0-9]+/, "").slice(0, 64);
		}
	};

	$("import-save").onclick = () => {
		const text = $("body").value.trim();
		const id = $("pid").value.trim();
		if (!text) return importError("The body is empty: select a .md file or paste its text.");
		if (text.length > MAX_TEXT) return importError(`Body is ${text.length} characters, exceeding the ${MAX_TEXT / 1024}KB limit; shorten it before saving.`);
		if (!ID_RE.test(id)) return importError("ID must start with a letter or digit and contain only letters, digits, dots, underscores, or hyphens (example: my-persona).");
		if (fixed().some((p) => p.id === id)) return importError(`ID "${id}" conflicts with a built-in persona; choose another.`);
		if (inline().length >= MAX_COUNT && !inline().some((p) => p.id === id)) {
			return importError(`At most ${MAX_COUNT} personas can be imported; remove some first.`);
		}
		const name = $("pname").value.trim() || metaOf(text).name || id;
		base = { ...base, inlinePersonas: [...inline().filter((p) => p.id !== id), { id, name, text }] };
		resetForm();
		paintImport();
		save({ persona: id }); // Import selects the persona for the next request
	};

	$("import-reset").onclick = () => resetForm();

	// Shortcut: delete the entire group; reimport the same ID to overwrite one. Add card buttons for individual deletion.
	$("del-all").onclick = () => {
		const selected = inline().some((p) => p.id === picked.persona);
		base = { ...base, inlinePersonas: [] };
		if (selected) picked = { ...picked, persona: "" }; // Selected persona was removed; return to follow mode
		paintImport();
		save({});
	};

	paintImport();
})();
